package com.example.data.model

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Room database entity representing a clinical prescription in MedConnect Pro.
 * Stores comprehensive EMR prescription data generated by the RapidRx clinical engine,
 * including cryptographic SHA-256 signature verification and tamper-proof QR audit data.
 */
@Entity(tableName = "prescriptions")
data class Prescription(
    @PrimaryKey
    val id: String,
    val appointmentId: String,
    val doctorId: String,
    val doctorName: String,
    val doctorQualifications: String,
    val doctorSpeciality: String,
    val councilRegistrationNumber: String,
    val clinicAffiliation: String,
    val patientId: String,
    val patientName: String,
    val patientAge: Int,
    val patientGender: String,
    val patientWeightKg: Double,
    val patientAllergies: String,
    val patientChronicConditions: String,
    val diagnosisICD10: String, // ICD-10 Code + Description
    val vitalsBp: String,
    val vitalsPulse: String,
    val vitalsSpO2: String,
    val vitalsTemp: String,
    val medicationsJson: String, // Serialized list of MedicationItem
    val clinicalAdviceJson: String, // List of advice tags
    val labOrdersJson: String, // Investigations
    val followUpText: String, // e.g. "After 7 Days"
    val followUpDateTimestamp: Long,
    val doctorSignatureHash: String,
    val verificationQrUrl: String,
    val createdAt: Long = System.currentTimeMillis()
)

/**
 * Type alias for backward compatibility across the codebase and EMR architecture.
 */
typealias PrescriptionEntity = Prescription
